<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useProject } from '@/composables/useProject'
import { repository } from '@/data/database'
import { drafts } from '@/data/drafts'
import { PhoneScanner, nativeScannerAvailable } from '@/scanner/native'
import { SOURCE_LABELS } from '@/domain/types'
import { errorMessage } from '@/domain/validation'
import { toast } from '@/composables/useToasts'
import AppIcon from '@/components/AppIcon.vue'
import PageHeading from '@/components/PageHeading.vue'
import SceneViewer from '@/components/SceneViewer.vue'
import EmptyState from '@/components/EmptyState.vue'
import NoticeBox from '@/components/NoticeBox.vue'
import ConfirmDialog from '@/components/ConfirmDialog.vue'
import PhotoGallery from '@/components/PhotoGallery.vue'
const route = useRoute(), router = useRouter(), id = computed(() => String(route.params.id)), { project, scenes, loading, error, reload } = useProject(id), confirm = ref(false), busy = ref(false)
const vertices = computed(() => project.value?.scenes.reduce((n, s) => n + s.vertexCount, 0) || 0)
async function favorite(): Promise<void> { if (!project.value) return; try { await repository.save({ ...project.value, favorite: !project.value.favorite }, project.value.revision); await reload() } catch (e) { toast(errorMessage(e), 'error') } }
async function remove(): Promise<void> { if (!project.value || busy.value) return; busy.value = true; try { await repository.remove(id.value, project.value.revision); try { await drafts.removeProject(id.value); if (nativeScannerAvailable()) { const captures = await PhoneScanner.getRecoveries(); for (const capture of captures.results.filter(r => r.projectId === id.value)) await PhoneScanner.discard({ sessionId: capture.sessionId }) } } catch { toast('Project removed, but recovery cleanup needs retrying on this device.', 'warning') } await router.push('/library'); toast('Project removed from this device.', 'success') } catch (e) { toast(errorMessage(e), 'error') } finally { busy.value = false; confirm.value = false } }
</script>
<template><div class="container"><div v-if="loading" class="loading-state" role="status">Opening your space…</div><NoticeBox v-if="error" kind="error">{{ error }}<button class="text-link" @click="reload">Try again</button><RouterLink to="/library">Back to spaces</RouterLink></NoticeBox><template v-if="project"><PageHeading back="/library" eyebrow="SPACE OVERVIEW" :title="project.name" :subtitle="project.location || 'Private workspace · saved on this device'"><button class="icon-button bordered" :aria-pressed="project.favorite" :aria-label="project.favorite ? 'Remove favorite' : 'Mark favorite'" @click="favorite"><AppIcon name="star"/></button><RouterLink :to="`/projects/${id}/edit`" class="btn btn-outline-primary"><AppIcon name="edit" :size="18"/>Edit space</RouterLink></PageHeading><NoticeBox v-if="project.scenes.some(s => s.source === 'sample')" kind="info">This project contains illustrative sample geometry. It is not a scan of an actual property.</NoticeBox><div class="project-overview-grid"><section class="preview-card card"><SceneViewer v-if="scenes.length" :scenes="scenes" :annotations="project.annotations" :grid="false"/><EmptyState v-else title="Ready for a new perspective." message="Start a supported on-device scan or import an existing 3D model."><RouterLink :to="`/projects/${id}/scan`" class="btn btn-primary"><AppIcon name="scan"/>Start capture</RouterLink></EmptyState><RouterLink v-if="scenes.length" :to="`/projects/${id}/view`" class="open-viewer btn btn-primary"><AppIcon name="eye"/>Explore in 3D<AppIcon name="arrow" :size="18"/></RouterLink></section><aside class="space-sidebar"><div class="card detail-card"><span class="eyebrow">THE DETAILS</span><div class="stat-pair"><span>Scan sections</span><strong>{{ project.scenes.length }}</strong></div><div class="stat-pair"><span>Vertices</span><strong>{{ vertices.toLocaleString() }}</strong></div><div class="stat-pair"><span>Room outlines</span><strong>{{ project.rooms.length }}</strong></div><div class="stat-pair"><span>Updated</span><strong>{{ new Date(project.updatedAt).toLocaleDateString() }}</strong></div><div class="local-note"><AppIcon name="lock" :size="17"/>Local-only project</div></div><div class="quick-actions"><RouterLink :to="`/projects/${id}/scan`"><AppIcon name="scan"/><span>Capture another section<small>Each scan starts in its own local origin.</small></span><AppIcon name="chevron"/></RouterLink><RouterLink :to="`/projects/${id}/import`"><AppIcon name="upload"/><span>Import a model<small>GLB, PLY or OBJ</small></span><AppIcon name="chevron"/></RouterLink><RouterLink :to="`/projects/${id}/floorplan`"><AppIcon name="map"/><span>Floor plan<small>Trace, name and export room outlines.</small></span><AppIcon name="chevron"/></RouterLink><RouterLink :to="`/projects/${id}/export`"><AppIcon name="download"/><span>Export & back up<small>Your files, in your hands.</small></span><AppIcon name="chevron"/></RouterLink></div></aside></div><section class="card detail-card"><div class="section-heading"><h2>Scan sections</h2><span class="count-pill">{{ project.scenes.length }}</span></div><div v-for="s in project.scenes" :key="s.id" class="scene-row"><span class="row-icon"><AppIcon name="cube"/></span><div><strong>{{ s.name }}</strong><p>{{ SOURCE_LABELS[s.source] }} · {{ s.vertexCount.toLocaleString() }} vertices · {{ s.triangleCount.toLocaleString() }} triangles</p><small v-if="s.warnings.length" class="muted">{{ s.warnings[0] }}</small></div><span class="status-badge" :class="s.status">{{ s.status === 'review' ? 'Needs review' : 'Saved' }}</span></div><p v-if="!project.scenes.length" class="muted">No scan sections yet. Reference photos and notes can still be saved.</p><NoticeBox v-if="project.scenes.length > 1">Sections do not automatically align across separate capture sessions. Use the editor’s transforms to align them against known features.</NoticeBox></section><PhotoGallery :project="project" @changed="reload"/><section class="card detail-card"><div class="section-heading"><h2>Space notes</h2><RouterLink :to="`/projects/${id}/edit`" class="text-link">Edit<AppIcon name="edit" :size="16"/></RouterLink></div><p class="pre-wrap">{{ project.notes || 'Add details that a model alone can’t tell.' }}</p></section><div class="project-bottom"><RouterLink to="/privacy" class="text-link"><AppIcon name="shield" :size="16"/>About local storage</RouterLink><button class="text-link danger-text" @click="confirm = true"><AppIcon name="trash" :size="16"/>Delete this space</button></div><ConfirmDialog v-if="confirm" title="Delete this space?" :message="`This removes ${project.name}, its scan data, photos and recovery captures from this device. Export a W3D backup first. Existing exported copies are not deleted.`" confirm-label="Delete space" danger :busy="busy" @cancel="confirm = false" @confirm="remove"/></template></div></template>
